const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
let db, current = 'overview', timer;
const localMonth = (() => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; })();
let reportMonth = localMonth;
const euro = n => new Intl.NumberFormat('it-IT',{style:'currency',currency:db.settings.currency||'EUR'}).format(Number(n)||0);
const stockThreshold = () => { const n=Number(db?.settings?.lowStockThreshold); return Number.isFinite(n)&&n>=0?Math.floor(n):2; };
const lowStockProducts = () => db.products.filter(p=>(Number(p.stock)||0)<=stockThreshold());
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt = d => d ? new Date(d).toLocaleDateString('it-IT') : '—';
const makeId = prefix => `${prefix}-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;
function persist(){ window.pokebricks.save(db); }
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),2600)}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><span class="eyebrow">POKEBRICKS · GESTIONALE</span><h1>${title}</h1><p class="sub">${desc}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`}
function btn(label,action,primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${action}">${label}</button>`}
function showModal(title,desc,fields,submitLabel,callback){$('#modalContent').innerHTML=`<h2>${title}</h2><p>${desc}</p><form id="entryForm"><div class="form-grid">${fields}</div><div class="modal-foot"><button type="button" class="btn" id="cancelForm">Annulla</button><button class="btn primary">${submitLabel}</button></div></form>`;$('#modal').classList.remove('hidden');$('#cancelForm').onclick=closeModal;$('#entryForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(callback(d)===false)return;closeModal();persist();render();};}
function field(label,name,type='text',placeholder='',required=true,full=false){return `<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':''}></div>`}
function closeModal(){$('#modal').classList.add('hidden')}
function stockRows(list){const threshold=stockThreshold();return list.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.sku||'—')}</td><td>${esc(p.category||'TCG')}</td><td>${Number(p.stock)||0}</td><td>${euro(p.cost)}</td><td>${euro(p.price)}</td><td><span class="badge ${(Number(p.stock)||0)<=threshold?'warn':''}">${(Number(p.stock)||0)<=threshold?'Scorta minima':'Disponibile'}</span></td><td><button class="btn small" data-action="delete-product" data-id="${esc(p.id)}">Rimuovi</button></td></tr>`).join('')}
function showStockAlerts(){const low=lowStockProducts(),threshold=stockThreshold();$('#modalContent').innerHTML=`<h2>Avvisi scorte</h2><p>Soglia impostata: ${threshold} unità o meno. Puoi modificarla in Impostazioni.</p>${low.length?`<div class="table-scroll"><table><thead><tr><th>PRODOTTO</th><th>SKU</th><th>DISPONIBILI</th></tr></thead><tbody>${low.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.sku||'—')}</td><td><span class="badge warn">${Number(p.stock)||0}</span></td></tr>`).join('')}</tbody></table></div><div class="modal-foot"><button class="btn" data-action="close-stock-alerts">Chiudi</button><button class="btn primary" data-action="open-alert-catalog">Apri catalogo</button></div>`:'<div class="empty"><b>Nessun prodotto sotto soglia</b>Le scorte sono sufficienti.</div><div class="modal-foot"><button class="btn" data-action="close-stock-alerts">Chiudi</button></div>'}`;$('#modal').classList.remove('hidden')}
function showUpdateNotifications(){const card=(title,description,purpose,where)=>'<div class="release-notice"><div class="release-notice-icon">♢</div><div><b>'+title+'</b><p>'+description+'</p><div class="release-detail"><b>A cosa serve</b><span>'+purpose+'</span></div><div class="release-detail"><b>Dove trovarla</b><span>'+where+'</span></div></div></div>';$('#modalContent').innerHTML='<span class="eyebrow">POKEBRICKS · NOVITÀ v0.1.11</span><h2 style="margin-top:9px">Centro notifiche aggiornamenti</h2><p>Qui trovi il riepilogo delle novità, il motivo per cui sono utili e dove aprirle.</p>'+card('Notifiche degli aggiornamenti','La campanella resta visibile nella barra superiore con un’animazione morbida.','Consultare in qualsiasi momento le novità e trovare le funzioni appena aggiunte.','Campanella in alto a destra, accanto agli avvisi scorte; disponibile da tutte le schermate.')+card('Resi e annullamenti','Registra un reso parziale o completo oppure annulla una vendita, indicando il motivo. La vendita originale resta nello storico.','Tracciare rimborsi, quantità restituite e andamento reale degli incassi. Se la vendita è collegata al catalogo, le unità rientrano automaticamente in magazzino.','Vendite live → pulsante “Reso / annulla” sulla vendita. Riepilogo e storico nel Report mensile.')+card('Stampa documenti','La stampa usa ora il dialogo del sistema senza errori di apertura finestra.','Stampare le bozze operative in modo affidabile.','Documenti → pulsante Stampa nella riga del documento.')+'<div class="modal-foot"><button class="btn primary" data-action="close-notifications">Ho capito</button></div>';$('#modal').classList.remove('hidden')}
function table(title,heads,rows,search='Cerca…'){return `<div class="table-panel"><div class="table-tools"><b>${title}</b><input class="search" placeholder="⌕  ${search}" data-search></div><div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}"><div class="empty"><b>Nessun elemento ancora</b>Aggiungi il primo elemento per iniziare.</div></td></tr>`}</tbody></table></div></div>`}
function overview(){const gross=db.sales.reduce((a,s)=>a+netSaleTotal(s),0), low=lowStockProducts().length, threshold=stockThreshold(), recent=[...db.sales].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5);
$('#page').innerHTML=pageHead('Panoramica','Tieni sotto controllo vendite, scorte e documenti.',`${btn('＋ Nuova vendita','new-sale',true)}${btn('＋ Aggiungi prodotto','new-product')}`)+`<div class="stats"><div class="stat"><div class="stat-top">Incasso registrato <span class="stat-icon">€</span></div><div class="stat-value">${euro(gross)}</div><div class="stat-foot">Totale vendite al netto di resi e annullamenti</div></div><div class="stat"><div class="stat-top">Vendite registrate <span class="stat-icon">↗</span></div><div class="stat-value">${db.sales.length}</div><div class="stat-foot">Da quando hai iniziato</div></div><div class="stat"><div class="stat-top">Prodotti in catalogo <span class="stat-icon">▦</span></div><div class="stat-value">${db.products.length}</div><div class="stat-foot">${db.products.reduce((a,p)=>a+Number(p.stock||0),0)} unità disponibili</div></div><div class="stat"><div class="stat-top">Scorte da controllare <span class="stat-icon">⌁</span></div><div class="stat-value">${low}</div><div class="stat-foot">Prodotti con ${threshold} unità o meno</div></div></div><div class="overview-grid"><div class="panel"><div class="panel-head"><h3>Andamento vendite</h3><span>Storico registrato</span></div><div class="chart"><svg viewBox="0 0 600 200" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e24842" stop-opacity=".18"/><stop offset="1" stop-color="#e24842" stop-opacity="0"/></linearGradient></defs><path d="M0 170 C70 160 80 125 150 140 S230 85 300 112 S390 55 450 90 S530 35 600 46 L600 200 L0 200Z" fill="url(#area)"/><path d="M0 170 C70 160 80 125 150 140 S230 85 300 112 S390 55 450 90 S530 35 600 46" fill="none" stroke="#e24842" stroke-width="3"/></svg></div><div class="chart-labels"><span>Inizio</span><span>Attività</span><span>Oggi</span></div></div><div class="panel"><div class="panel-head"><h3>Attività recente</h3><span>${recent.length} movimenti</span></div><div class="activity">${recent.length?recent.map(s=>`<div class="activity-row"><div class="activity-icon">↗</div><div class="activity-copy"><b>${esc(s.product)}</b><small>${esc(s.customer||'Cliente occasionale')} · ${dateFmt(s.createdAt)}</small></div><span class="activity-amount">${euro(s.total)}</span></div>`).join(''):`<div class="empty"><b>Ancora nessuna attività</b>Le vendite recenti appariranno qui.</div>`}</div></div></div><div style="margin-top:17px">${table('Ultime vendite',['RIFERIMENTO','PRODOTTO','CLIENTE','DATA','IMPORTO'],recent.map(s=>`<tr><td><b>${esc(s.id)}</b></td><td>${esc(s.product)}</td><td>${esc(s.customer||'Occasionale')}</td><td>${dateFmt(s.createdAt)}</td><td><b>${euro(s.total)}</b></td></tr>`),'Cerca vendite')}</div>`}
function products(){ $('#page').innerHTML=pageHead('Catalogo prodotti','Gestisci articoli, prezzi e disponibilità.',`${btn('↓ Modello CSV','product-csv-template')}${btn('↑ Importa CSV','product-csv-import')}${btn('＋ Nuovo prodotto','new-product',true)}`)+`<input id="productCsvFile" type="file" accept=".csv,text/csv" hidden>`+table('Tutti i prodotti',['PRODOTTO','SKU','CATEGORIA','Q.TÀ','COSTO','PREZZO','STATO',''],stockRows(db.products),'Cerca per nome o SKU'); }
function csvDelimiter(line){let commas=0,semicolons=0,quoted=false;for(let i=0;i<line.length;i++){if(line[i]==='"'){if(quoted&&line[i+1]==='"'){i++;continue}quoted=!quoted}else if(!quoted){if(line[i]===',')commas++;if(line[i]===';')semicolons++}}return semicolons>=commas?';':','}
function parseCsv(text,delimiter){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell.length||row.length){row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row)}if(quoted)throw new Error('Il CSV contiene una cella tra virgolette non chiusa.');return rows}
function csvNumber(value){let s=String(value??'').trim().replace(/\s/g,'');if(!s)return 0;if(s.includes(',')&&s.includes('.')){if(s.lastIndexOf(',')>s.lastIndexOf('.'))s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else s=s.replace(',','.');const n=Number(s);if(!Number.isFinite(n)||n<0)throw new Error('valore numerico non valido');return n}
function importProductCsv(text){const clean=text.replace(/^\uFEFF/,'');const firstLine=clean.split(/\r?\n/).find(line=>line.trim());if(!firstLine)throw new Error('Il file CSV è vuoto.');const rows=parseCsv(clean,csvDelimiter(firstLine));if(rows.length<2)throw new Error('Il CSV deve contenere una riga di intestazioni e almeno un prodotto.');const normalize=value=>String(value||'').trim().toLocaleLowerCase('it-IT').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s_-]/g,'');const headers=rows[0].map(normalize);const index=names=>headers.findIndex(h=>names.includes(h));const columns={name:index(['nome','prodotto','nomeprodotto','name','product']),sku:index(['sku','codice','codiceprodotto']),category:index(['categoria','category']),stock:index(['giacenza','stock','quantita','qta','quantity']),cost:index(['costo','cost']),price:index(['prezzo','price'])};if(columns.name<0||columns.price<0)throw new Error('Servono almeno le colonne nome (o name) e prezzo (o price).');const value=(row,col)=>col<0?'':String(row[col]??'').trim();const key=p=>normalize(p);const knownSku=new Set(db.products.map(p=>key(p.sku)).filter(Boolean));const knownNames=new Set(db.products.map(p=>key(p.name)).filter(Boolean));const staged=[],errors=[];for(let i=1;i<rows.length;i++){const row=rows[i],line=i+1,name=value(row,columns.name);if(!name){errors.push(`riga ${line}: nome mancante`);continue}const sku=value(row,columns.sku),nameKey=key(name),skuKey=key(sku);if(knownNames.has(nameKey)||(skuKey&&knownSku.has(skuKey))){errors.push(`riga ${line}: prodotto o SKU già presente`);continue}try{const stock=csvNumber(value(row,columns.stock)),cost=csvNumber(value(row,columns.cost)),price=csvNumber(value(row,columns.price));if(!Number.isInteger(stock))throw new Error('la giacenza deve essere un numero intero');if(price<=0)throw new Error('il prezzo deve essere maggiore di zero');staged.push({id:makeId('PRD'),name,sku,category:value(row,columns.category)||'TCG',stock,cost,price});knownNames.add(nameKey);if(skuKey)knownSku.add(skuKey)}catch(error){errors.push(`riga ${line}: ${error.message}`)}}return{staged,errors}}
function downloadProductCsvTemplate(){const content='\uFEFFnome;sku;categoria;giacenza;costo;prezzo\r\n';const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='modello-catalogo-pokebricks.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Modello CSV scaricato')}
async function handleProductCsv(input){const file=input.files?.[0];if(!file)return;try{const{staged,errors}=importProductCsv(await file.text());if(!staged.length)throw new Error(errors.length?`Nessun prodotto importabile. ${errors.slice(0,4).join('; ')}`:'Il CSV non contiene prodotti validi.');const preview=staged.slice(0,5).map(p=>`• ${p.name} · ${p.stock} unità · ${euro(p.price)}`).join('\n');const skipped=errors.length?`\n\nRighe saltate: ${errors.length}. ${errors.slice(0,4).join('; ')}`:'';if(!window.confirm(`Importare ${staged.length} prodotti nel catalogo?\n\n${preview}${staged.length>5?'\n• …':''}${skipped}`))return;db.products.push(...staged);await window.pokebricks.save(db);render();toast(`${staged.length} prodotti importati${errors.length?`; ${errors.length} righe saltate`:''}`)}catch(error){toast(error.message||'Importazione CSV non riuscita')}finally{input.value=''}}
function returnedQuantity(s){return(Array.isArray(s.returns)?s.returns:[]).reduce((sum,r)=>sum+Math.max(0,Number(r.quantity)||0),0)}
function remainingSaleQuantity(s){return Math.max(0,(Number(s.quantity)||0)-returnedQuantity(s))}
function returnedAmount(s){return(Array.isArray(s.returns)?s.returns:[]).reduce((sum,r)=>sum+Math.max(0,Number(r.amount)||0),0)}
function netSaleTotal(s){return Math.max(0,(Number(s.total)||0)-returnedAmount(s))}
function estimateRefund(s,quantity,remaining){const leftAmount=Math.max(0,(Number(s.total)||0)-returnedAmount(s)),originalQty=Number(s.quantity)||0;if(quantity===remaining)return leftAmount;return originalQty>0?Math.round(((Number(s.total)||0)/originalQty*quantity)*100)/100:0}
function saleStatus(s){const returns=Array.isArray(s.returns)?s.returns:[];if(!returns.length)return'Completata';if(remainingSaleQuantity(s)===0)return returns.some(r=>r.kind==='annullamento')?'Annullata':'Reso completo';return'Reso parziale'}
function saleProduct(s){if(s.productId){const linked=db.products.find(p=>p.id===s.productId);if(linked)return{product:linked,ambiguous:false}}const matches=db.products.filter(p=>String(p.name||'').trim().toLocaleLowerCase('it-IT')===String(s.product||'').trim().toLocaleLowerCase('it-IT'));return matches.length===1?{product:matches[0],ambiguous:false}:{product:null,ambiguous:matches.length>1}}
function sales(){ $('#page').innerHTML=pageHead('Vendite live','Registra le vendite e gestisci resi e annullamenti senza cancellare lo storico.',btn('＋ Registra vendita','new-sale',true))+table('Registro vendite',['RIFERIMENTO','PRODOTTO','CLIENTE','DATA','Q.TÀ RESIDUA','STATO','TOTALE NETTO','AZIONI'],[...db.sales].reverse().map(s=>{const rem=remainingSaleQuantity(s),status=saleStatus(s),history=Array.isArray(s.returns)?s.returns.length:0;return`<tr><td><b>${esc(s.id)}</b></td><td>${esc(s.product)}</td><td>${esc(s.customer||'Occasionale')}</td><td>${dateFmt(s.createdAt)}</td><td>${rem} / ${Number(s.quantity)||0}</td><td><span class="badge ${rem===0?'gray':history?'warn':''}">${status}</span></td><td><b>${euro(netSaleTotal(s))}</b></td><td>${rem>0?`<button class="btn small" data-action="return-sale" data-id="${esc(s.id)}">Reso / annulla</button>`:''}${history?` <button class="btn small" data-action="show-sale-returns" data-id="${esc(s.id)}">Storico</button>`:''}</td></tr>`}),'Cerca vendita o cliente'); }
function reportSalesForMonth(){return db.sales.filter(s=>String(s.createdAt||'').slice(0,7)===reportMonth).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
function reportReturnsForMonth(){return db.sales.flatMap(s=>(Array.isArray(s.returns)?s.returns:[]).filter(r=>String(r.createdAt||'').slice(0,7)===reportMonth).map(r=>({sale:s,entry:r}))).sort((a,b)=>String(b.entry.createdAt||'').localeCompare(String(a.entry.createdAt||'')))}
function reports(){
  const list=reportSalesForMonth(),returns=reportReturnsForMonth(),gross=list.reduce((sum,s)=>sum+(Number(s.total)||0),0),refunds=returns.reduce((sum,r)=>sum+(Number(r.entry.amount)||0),0),net=gross-refunds,average=list.length?gross/list.length:0;
  const methods={};list.forEach(s=>{const name=(s.payment||'').trim()||'Non indicato';methods[name]=(methods[name]||0)+Number(s.total||0)});returns.forEach(({sale,entry})=>{const name=(sale.payment||'').trim()||'Non indicato';methods[name]=(methods[name]||0)-(Number(entry.amount)||0)});
  const methodRows=Object.entries(methods).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="activity-row"><div class="activity-copy"><b>${esc(name)}</b><small>Saldo del periodo</small></div><span class="activity-amount">${euro(value)}</span></div>`).join('')||'<div class="empty"><b>Nessun movimento</b>Non ci sono vendite o resi per il mese selezionato.</div>';
  const rows=list.map(s=>`<tr><td><b>${esc(s.id||'—')}</b></td><td>${esc(s.product||'—')}</td><td>${esc(s.customer||'Occasionale')}</td><td>${dateFmt(s.createdAt)}</td><td>${Number(s.quantity)||0}</td><td>${esc(s.payment||'Non indicato')}</td><td><b>${euro(s.total)}</b></td><td>${euro(returnedAmount(s))}</td><td><b>${euro(netSaleTotal(s))}</b></td></tr>`).join('');
  const returnRows=returns.map(({sale,entry})=>`<tr><td>${dateFmt(entry.createdAt)}</td><td><b>${esc(sale.id||'—')}</b></td><td>${esc(sale.product||'—')}</td><td>${entry.kind==='annullamento'?'Annullamento':'Reso'}</td><td>${Number(entry.quantity)||0}</td><td>${esc(entry.reason||'—')}</td><td><b>${euro(entry.amount)}</b></td></tr>`).join('');
  $('#page').innerHTML=pageHead('Report mensile','Riepiloga vendite, resi e annullamenti ed esporta un prospetto CSV.',btn('↓ Esporta CSV','export-report',true))+`<div class="panel" style="margin-bottom:16px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap"><div><b>Periodo del report</b><div class="stat-foot" style="margin-top:5px">Vendite per data di vendita; resi per data di registrazione</div></div><input id="reportMonth" type="month" value="${esc(reportMonth)}" aria-label="Seleziona mese"></div><div class="stats report-stats"><div class="stat"><div class="stat-top">Vendite lorde</div><div class="stat-value">${euro(gross)}</div><div class="stat-foot">Vendite registrate nel mese</div></div><div class="stat"><div class="stat-top">Resi e annullamenti</div><div class="stat-value">${euro(refunds)}</div><div class="stat-foot">Registrati nel mese</div></div><div class="stat"><div class="stat-top">Saldo netto</div><div class="stat-value">${euro(net)}</div><div class="stat-foot">Vendite del mese meno resi registrati</div></div><div class="stat"><div class="stat-top">Vendite</div><div class="stat-value">${list.length}</div><div class="stat-foot">Transazioni registrate</div></div><div class="stat"><div class="stat-top">Valore medio lordo</div><div class="stat-value">${euro(average)}</div><div class="stat-foot">Per vendita</div></div></div><div class="panel" style="margin-bottom:16px"><div class="panel-head"><h3>Saldo per metodo di pagamento</h3><span>${list.length} vendite · ${returns.length} resi</span></div><div class="activity">${methodRows}</div></div>${table('Dettaglio vendite',['RIFERIMENTO','PRODOTTO','CLIENTE','DATA','Q.TÀ','PAGAMENTO','LORDO','RESI','NETTO'],rows,'Cerca nel report')}${table('Resi e annullamenti del mese',['DATA','RIFERIMENTO','PRODOTTO','TIPO','Q.TÀ','MOTIVO','IMPORTO'],returnRows,'Cerca nei resi')}<div class="notice" style="margin-top:14px">Il saldo è un prospetto operativo calcolato dalle registrazioni locali. Non sostituisce registri o documenti fiscali.</div>`;
}
function exportMonthlyReport(){
  const list=reportSalesForMonth(),returns=reportReturnsForMonth(),gross=list.reduce((sum,s)=>sum+(Number(s.total)||0),0),refunds=returns.reduce((sum,r)=>sum+(Number(r.entry.amount)||0),0),net=gross-refunds;
  const cells=values=>values.map(value=>{if(typeof value==='number')return String(value).replace('.',',');const text=String(value??'');return `"${(/^[\t\r ]*[=+\-@]/.test(text)?"'":"")}${text.replaceAll('"','""')}"`;}).join(';');
  const lines=[cells(['POKEBRICKS - Report vendite e resi',reportMonth]),cells(['Numero vendite',list.length]),cells(['Vendite lorde',gross]),cells(['Resi e annullamenti registrati nel mese',refunds]),cells(['Saldo netto del periodo',net]),'',cells(['Vendite']),cells(['Riferimento','Prodotto','Cliente','Data','Quantità','Metodo pagamento','Totale lordo','Resi complessivi','Netto vendita'])];
  list.forEach(s=>lines.push(cells([s.id||'',s.product||'',s.customer||'Occasionale',s.createdAt?new Date(s.createdAt).toLocaleDateString('it-IT'):'',Number(s.quantity)||0,s.payment||'Non indicato',Number(s.total)||0,returnedAmount(s),netSaleTotal(s)])));
  lines.push('',cells(['Resi e annullamenti registrati nel mese']),cells(['Data','Riferimento vendita','Prodotto','Tipo','Quantità','Motivo','Importo']));
  returns.forEach(({sale,entry})=>lines.push(cells([entry.createdAt?new Date(entry.createdAt).toLocaleDateString('it-IT'):'',sale.id||'',sale.product||'',entry.kind==='annullamento'?'Annullamento':'Reso',Number(entry.quantity)||0,entry.reason||'',Number(entry.amount)||0])));
  const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}), url=URL.createObjectURL(blob), a=document.createElement('a');
  a.href=url;a.download=`pokebricks-report-vendite-${reportMonth}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report CSV esportato');
}
