function startProduct(){showModal('Aggiungi prodotto','Inserisci le informazioni principali dell’articolo.',field('Nome prodotto','name','text','es. Pokémon ETB Destino di Paldea',true,true)+field('SKU / codice','sku','text','es. PKM-ETB-001',false)+field('Categoria','category','text','es. Pokémon TCG')+field('Quantità disponibile','stock','number','0')+field('Costo unitario (€)','cost','number','0')+field('Prezzo vendita (€)','price','number','0'),'Salva prodotto',d=>db.products.push({id:makeId('PRD'),...d,stock:Number(d.stock),cost:Number(d.cost),price:Number(d.price)}));}
function startSale(){const options=db.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${euro(p.price)} (${p.stock} disp.)</option>`).join('');const productField=options?`<div class="field full"><label>Prodotto</label><select name="productId" required>${options}</select></div>`:field('Prodotto venduto','product','text','Nome prodotto',true,true);showModal('Registra vendita','Salva la transazione e aggiorna le scorte.',productField+field('Cliente','customer','text','Occasionale o nome cliente',false)+field('Quantità','quantity','number','1')+field('Prezzo unitario (€)','price','number',options?'Compilato dal catalogo':'0')+field('Metodo di pagamento','payment','text','es. PayPal, contanti',false),'Registra vendita',d=>{const p=d.productId?db.products.find(x=>x.id===d.productId):null;const quantity=Number(d.quantity);if(p&&p.stock<quantity){toast('Quantità superiore alle scorte');return false}if(p){p.stock-=quantity;}db.sales.push({id:makeId('VND'),productId:p?.id||null,product:p?.name||d.product,customer:d.customer,quantity,total:quantity*(p?Number(p.price):Number(d.price)),payment:d.payment,createdAt:new Date().toISOString(),returns:[]});});const sel=$('#entryForm select[name="productId"]');if(sel){const update=()=>{$('#entryForm [name="price"]').value=db.products.find(p=>p.id===sel.value)?.price||0};sel.onchange=update;update();}}
function startReturn(saleId){const sale=db.sales.find(s=>s.id===saleId);if(!sale)return;const remaining=remainingSaleQuantity(sale);if(remaining<=0){toast('Questa vendita non ha quantità residue');return}const link=saleProduct(sale);const stockNote=link.product?'L’articolo '+esc(link.product.name)+' è collegato al catalogo: le quantità restituite saranno ricaricate automaticamente.':link.ambiguous?'Più articoli hanno questo nome: il reso sarà registrato senza modificare le scorte.':'La vendita non è collegata al catalogo: il reso sarà registrato senza modificare le scorte.';const fields='<div class="field full"><label>Operazione</label><select name="kind"><option value="reso">Reso parziale o completo</option><option value="annullamento">Annullamento totale ('+remaining+' unità residue)</option></select></div><div class="field"><label>Quantità da restituire</label><input name="quantity" type="number" min="1" max="'+remaining+'" step="1" value="1" required></div><div class="field"><label>Importo stimato</label><input id="returnEstimate" value="'+euro(estimateRefund(sale,1,remaining))+'" readonly></div><div class="field full"><label>Motivo</label><input name="reason" maxlength="240" placeholder="es. articolo danneggiato, ordine annullato" required></div><div class="field full"><div class="notice" style="margin:0">'+stockNote+' Il rimborso è calcolato dal totale originale.</div></div>';showModal('Registra reso o annullamento','Vendita '+esc(sale.id)+' · '+esc(sale.product)+' · '+remaining+' unità ancora restituibili.',fields,'Conferma registrazione',d=>{const quantity=d.kind==='annullamento'?remaining:Number(d.quantity);if(!Number.isInteger(quantity)||quantity<1||quantity>remaining){toast('Inserisci una quantità intera da 1 a '+remaining);return false}const amount=estimateRefund(sale,quantity,remaining);sale.returns=Array.isArray(sale.returns)?sale.returns:[];sale.returns.push({id:makeId('RET'),kind:d.kind,quantity,amount,reason:d.reason.trim(),createdAt:new Date().toISOString()});if(link.product)link.product.stock=(Number(link.product.stock)||0)+quantity;else toast(link.ambiguous?'Reso salvato; articolo non univoco, scorte invariate.':'Reso salvato; nessun collegamento al catalogo, scorte invariate.');});const kind=$('#entryForm [name="kind"]'),qty=$('#entryForm [name="quantity"]');const refreshEstimate=()=>{$('#returnEstimate').value=euro(estimateRefund(sale,kind.value==='annullamento'?remaining:Number(qty.value),remaining))};kind.onchange=()=>{const cancel=kind.value==='annullamento';qty.readOnly=cancel;qty.value=cancel?remaining:1;refreshEstimate()};qty.oninput=refreshEstimate}
function showSaleReturns(saleId){const sale=db.sales.find(s=>s.id===saleId);if(!sale)return;const rows=(Array.isArray(sale.returns)?sale.returns:[]).map(r=>'<tr><td>'+dateFmt(r.createdAt)+'</td><td>'+(r.kind==='annullamento'?'Annullamento':'Reso')+'</td><td>'+(Number(r.quantity)||0)+'</td><td>'+esc(r.reason||'—')+'</td><td><b>'+euro(r.amount)+'</b></td></tr>').join('');$('#modalContent').innerHTML='<h2>Storico resi · '+esc(sale.id)+'</h2><p>'+esc(sale.product)+' · Importo originale '+euro(sale.total)+' · Rimborsato '+euro(returnedAmount(sale))+'</p>'+table('Movimenti registrati',['DATA','OPERAZIONE','Q.TÀ','MOTIVO','IMPORTO'],rows)+'<div class="modal-foot"><button class="btn" data-action="close-modal">Chiudi</button></div>';$('#modal').classList.remove('hidden')}
function startDocument(){const f=db.settings.fiscalProfile||{},configuredRate=db.settings.taxSetup?.defaultVatRate??'';const natureOptions=[['','Seleziona Natura IVA'],['N1','N1 · Escluse ex art. 15'],['N2.1','N2.1 · Non soggette art. 7-7-septies'],['N2.2','N2.2 · Altre non soggette'],['N3.1','N3.1 · Non imponibili esportazioni'],['N3.2','N3.2 · Cessioni intracomunitarie'],['N3.3','N3.3 · Cessioni verso San Marino'],['N3.4','N3.4 · Operazioni assimilate'],['N3.5','N3.5 · A seguito di dichiarazioni d’intento'],['N3.6','N3.6 · Altre non imponibili'],['N4','N4 · Esenti'],['N5','N5 · Regime del margine'],['N6.1','N6.1 · Inversione contabile rottami'],['N6.2','N6.2 · Inversione contabile oro'],['N6.3','N6.3 · Inversione contabile subappalto'],['N6.4','N6.4 · Inversione contabile cessione fabbricati'],['N6.5','N6.5 · Inversione contabile telefoni'],['N6.6','N6.6 · Inversione contabile elettronica'],['N6.7','N6.7 · Inversione contabile edilizia'],['N6.8','N6.8 · Inversione contabile altri settori'],['N6.9','N6.9 · Altri casi'],['N7','N7 · IVA assolta in altro Stato UE']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('');const fields=`<div class="notice field full">Seleziona Fattura per compilare i dati fiscali e poi esportare l’XML FatturaPA. Totale lordo di bozza. Inserisci aliquota e Natura solo dopo aver verificato il trattamento applicabile; il programma non determina il regime fiscale.</div><div class="field full"><label>Tipo documento</label><select name="type"><option>Preventivo</option><option>Documento di trasporto (bozza)</option><option>Ricevuta non fiscale</option><option>Fattura (bozza non trasmessa)</option></select></div><div class="field full"><label>Cliente / destinatario</label><input name="customer" required></div><div class="field"><label>Partita IVA cliente</label><input name="vatNumber"></div><div class="field"><label>Codice fiscale cliente</label><input name="fiscalCode"></div><div class="field full"><label>Indirizzo</label><input name="address" required></div><div class="field"><label>CAP</label><input name="postalCode" maxlength="10"></div><div class="field"><label>Comune</label><input name="city"></div><div class="field"><label>Provincia</label><input name="province" maxlength="2"></div><div class="field"><label>Nazione</label><input name="customerCountry" maxlength="2" value="IT"></div><div class="field"><label>Codice destinatario</label><input name="recipientCode" maxlength="7" placeholder="0000000 per privati"></div><div class="field"><label>PEC destinatario</label><input name="pec" type="email"></div><div class="field full"><label>Descrizione articolo / servizio</label><input name="description" required></div><div class="field"><label>Quantità</label><input name="quantity" type="number" min="1" step="1" value="1" required></div><div class="field"><label>Totale lordo IVA inclusa (€)</label><input name="total" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Aliquota IVA (%)</label><input name="vatRate" type="number" min="0" max="100" step="0.01" value="${esc(configuredRate)}" required></div><div class="field"><label>Natura IVA (obbligatoria con aliquota 0)</label><select name="vatNature">${natureOptions}</select></div><div class="field full"><label>Note</label><input name="notes"></div>`;showModal('Nuovo documento','Compila i dati del documento. Per una fattura elettronica XML servono anche il profilo emittente completo e i dati fiscali del cliente.',fields,'Salva bozza',d=>db.documents.push({id:makeId('DOC'),number:`D-${String(db.documents.length+1).padStart(4,'0')}`,...d,quantity:Number(d.quantity),total:Number(d.total),vatRate:Number(d.vatRate),date:new Date().toISOString()}));}
function exportInvoiceXml(id){const d=db.documents.find(x=>x.id===id);if(!d||!String(d.type||'').includes('Fattura'))return;let xml=d.xml;if(!xml){try{const result=window.fatturapa.generate(d,db.settings.fiscalProfile||{});xml=result.xml;d.xml=xml;d.sdi={status:'da_inviare',xmlExportedAt:new Date().toISOString(),...(d.sdi||{})};d.downloadName=result.fileName;persist();render()}catch(error){toast(error.message||'Impossibile generare XML FatturaPA');return}}const url=URL.createObjectURL(new Blob([xml],{type:'application/xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=d.downloadName||('fattura-'+String(d.number||'').replace(/[^A-Za-z0-9_-]/g,'')+'.xml');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('XML preparato e scaricato. Verifica tracciato e dati prima di trasmetterlo, poi registra qui la ricevuta SDI')}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){current=nav.dataset.page;render();return}const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'new-product':startProduct();break;case'new-sale':startSale();break;case'new-document':startDocument();break;case'return-sale':startReturn(b.dataset.id);break;case'show-sale-returns':showSaleReturns(b.dataset.id);break;case'close-modal':closeModal();break;case'export-report':exportMonthlyReport();break;case'product-csv-import':$('#productCsvFile')?.click();break;case'product-csv-template':downloadProductCsvTemplate();break;case'choose-backup':$('#backupFile')?.click();break;case'show-stock-alerts':showStockAlerts();break;case'show-update-notifications':showUpdateNotifications();break;case'close-notifications':closeModal();break;case'close-stock-alerts':$('#modal').classList.add('hidden');break;case'open-alert-catalog':$('#modal').classList.add('hidden');current='products';render();break;case'delete-product':db.products=db.products.filter(p=>p.id!==b.dataset.id);persist();render();toast('Prodotto rimosso');break;case'export-invoice-xml':exportInvoiceXml(b.dataset.id);break;case'update-sdi-status':updateSdiStatus(b.dataset.id);break;case'export-invoice-register':exportInvoiceRegister();break;case'print-doc':printDoc(b.dataset.id);break;case'export':{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`pokebricks-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Copia dati esportata');break}}});
document.addEventListener('change',e=>{if(e.target.matches('#productCsvFile'))handleProductCsv(e.target)});
document.addEventListener('change',async e=>{if(!e.target.matches('#backupFile'))return;const input=e.target,file=input.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());const valid=imported&&typeof imported==='object'&&!Array.isArray(imported)&&imported.settings&&typeof imported.settings==='object'&&!Array.isArray(imported.settings)&&Array.isArray(imported.products)&&Array.isArray(imported.sales)&&Array.isArray(imported.documents)&&[...imported.products,...imported.sales,...imported.documents].every(item=>item&&typeof item==='object'&&!Array.isArray(item));if(!valid)throw new Error('Il file selezionato non ha il formato di un backup POKEBRICKS.');const summary=`Il backup contiene ${imported.products.length} prodotti, ${imported.sales.length} vendite e ${imported.documents.length} documenti.\n\nI dati attuali saranno salvati in una copia di sicurezza prima del ripristino. Vuoi continuare?`;if(!window.confirm(summary))return;await window.pokebricks.restore(imported);db=await window.pokebricks.load();document.documentElement.style.setProperty('--red',db.settings.accent||'#e24842');render();toast('Backup ripristinato; copia di sicurezza creata')}catch(error){toast(error.message||'Impossibile ripristinare il backup')}finally{input.value=''}});
document.addEventListener('change',e=>{if(e.target.matches('#reportMonth')&&/^\d{4}-\d{2}$/.test(e.target.value)){reportMonth=e.target.value;render()}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-search]'))return;const q=e.target.value.toLowerCase();$$('#page tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));});$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#today').textContent=new Date().toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
function updateNotesText(notes){const entries=Array.isArray(notes)?notes.map(n=>typeof n==='string'?n:(n?.note||'')).filter(Boolean):[typeof notes==='string'?notes:''];let text=entries.join('\n\n');if(/<\/?(h[1-6]|p|ul|ol|li|br|div)\b/i.test(text)){text=text.replace(/<br\s*\/?\s*>/gi,'\n').replace(/<li\b[^>]*>/gi,'• ').replace(/<\/(h[1-6]|p|li|div|ul|ol)\s*>/gi,'\n');const parsed=new DOMParser().parseFromString(text,'text/html');text=parsed.body.textContent||''}return text.replace(/^[ \t]*#{1,6}[ \t]*/gm,'').replace(/^[ \t]*[-*][ \t]+/gm,'• ').replace(/`/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
function showUpdateNotes(notes){const box=$('#updateNotes'),text=updateNotesText(notes);box.textContent=text;box.classList.toggle('hidden',!text)}
function updateStatus(s){const overlay=$('#updateOverlay');if(s.state==='available'){toast(`Aggiornamento ${s.version} disponibile · download in corso`);$('#updateTitle').textContent=`Aggiornamento ${s.version} disponibile`;$('#updateText').textContent='Novità di questa versione e posizione della nuova funzione:';showUpdateNotes(s.releaseNotes);overlay.classList.remove('hidden')}if(s.state==='downloaded'){$('#updateTitle').textContent='Aggiornamento pronto';$('#updateText').textContent=`Versione ${s.version} scaricata e pronta da installare.`;showUpdateNotes(s.releaseNotes);$('#progressBar').style.width='100%';$('#progressPercent').textContent='100%';$('#progressLabel').textContent='Download completato';overlay.classList.remove('hidden');let n=5;const note=$('#restartNote');note.classList.remove('hidden');note.textContent=`Riavvio automatico tra ${n} secondi…`;const t=setInterval(()=>{n--;note.textContent=n>0?`Riavvio automatico tra ${n} secondi…`:'Riavvio in corso…';if(n<=0){clearInterval(t);window.pokebricks.installUpdate()}},1000)}if(s.state==='error'){const detail=String(s.message||'Errore non specificato').replace(/\s+/g,' ').slice(0,180);if(!overlay.classList.contains('hidden')){$('#updateTitle').textContent='Aggiornamento non riuscito';$('#updateText').textContent=`${detail} L’app continuerà a funzionare con la versione installata.`}else toast(`Aggiornamento non riuscito: ${detail}`)} }
window.pokebricks.onUpdateStatus(updateStatus);window.pokebricks.onUpdateProgress(p=>{const overlay=$('#updateOverlay');overlay.classList.remove('hidden');$('#updateTitle').textContent='Download aggiornamento';$('#updateText').textContent='La tua area di lavoro resterà salvata in modo sicuro.';$('#progressBar').style.width=`${p.percent}%` ;$('#progressPercent').textContent=`${p.percent}%`;$('#progressLabel').textContent=`${(p.transferred/1048576).toFixed(1)} MB di ${(p.total/1048576).toFixed(1)} MB`});
